fn step_terrain_fill(
    world: &mut World,
    gv: &mut GenVars,
    streams: &mut Streams,
    _opts: &GenOptions,
    noise: &Noise,
    _pass_config: &ConfigSection,
) {
    let (width, height) = (world.width, world.height);
    let map = gv
        .map
        .as_ref()
        .expect("the terrain height-map step did not run");
    let layers = terrain::fill_terrain(world, width, height, noise, map);
    // `TerrainPass`'s water/lava lines (`TerrainPass.cs:211-236`):
    // `num13 = (int)(rockLayer + maxTilesY) / 2 + Next(-100, 20)` →
    // `GenVars.waterLine`, `lavaLine = num13 + Next(50, 80)`. Drawn from the
    // pass's own fresh stream (the per-pass contract) — the port's Terrain
    // stand-in otherwise draws nothing, so no existing draw shifts.
    let (water_line, lava_line) = {
        let mut trng = streams.pass_rng("Terrain");
        let water_line = ((layers.rock_layer + height as f64) as i32) / 2 + trng.range(-100, 20);
        let lava_line = water_line + trng.range(50, 80);
        (water_line, lava_line)
    };
    gv.water_line = water_line;
    gv.lava_line = lava_line;
    // The chest-stocking seam reads it off the World (the `ChestSiteEvent`
    // `lava_line` field, W4-c33) - publish the drawn value beside the tiers.
    world.lava_line = lava_line;
    // `TerrainPass` publishes `Main.worldSurface`/`Main.rockLayer` at the
    // end of the terrain step (`TerrainPass.cs`), and EVERY later pass reads
    // them (the floating-island column scan, the campsite bands, the honey
    // patches, …). The world tail used to set them last, leaving the passes
    // on `World::new`'s `height/4` placeholder — publish them here.
    world.world_surface = layers.world_surface;
    world.rock_layer = layers.rock_layer;
    gv.layers = Some(layers);
}

fn step_plan_biome_spans(
    world: &mut World,
    gv: &mut GenVars,
    streams: &mut Streams,
    opts: &GenOptions,
    _noise: &Noise,
    _pass_config: &ConfigSection,
) {
    // `Reset`'s jungle origin draw (`WorldGen.cs:11341-11376`): the port's
    // Reset stand-in draws `Next(15, 30)` from a fresh "Jungle" stream — the
    // dungeon-side sign is fixed Right because the port's dungeon sits on
    // the right (`plan_spans`' `dungeon_x`), so the C# `Next(2)` side draw
    // (`:11348`) is not portable. The pass consumes `jungle_origin_x`
    // without redrawing. M5-SEED-1: the two seed range arms — remix widens
    // the band to `Next(20, 35)` (`WorldGen.cs:11247`) and the anniversary
    // world to `Next(25, 35)` (`:11360-11370`, remix-disabled) — replace the
    // range only, so a classic world's draw is unchanged.
    let jungle_origin_x = {
        let mut origin_rng = streams.pass_rng("Jungle");
        let (lo, hi) = if opts.flags.contains(crate::seeds::SeedFlags::REMIX) {
            (20, 35)
        } else if opts.flags.contains(crate::seeds::SeedFlags::TENTH_ANNIVERSARY) {
            (25, 35)
        } else {
            (15, 30)
        };
        let percent = origin_rng.range(lo, hi);
        (world.width as f64 * (percent as f64 * 0.01)) as i32
    };
    gv.jungle_origin_x = jungle_origin_x;
    let (width, left_beach_end, right_beach_start) = {
        let map = gv.map();
        (world.width, map.left_beach_end, map.right_beach_start)
    };
    let surface = gv.map().heights.clone();
    gv.spans = Some(biomes::plan_spans(
        width,
        &surface,
        left_beach_end,
        right_beach_start,
        jungle_origin_x,
    ));
}

/// W4-f24 A4: the gated `Skyblock` pass (`WorldGen.cs:11511-11515` →
/// `GenerateSkyBlockWorld` `:22526-22816`). Registered only under
/// `WorldGen.skyblockWorldGen` (the port's `SeedFlags::SKYBLOCK`); a classic
/// world's step is a no-op. The generator clears the terrain tiles and
/// places the island archipelago; the denyAll/denySome pruning (A1) skips
/// the classic passes that would otherwise overwrite it.
fn step_skyblock(
    world: &mut World,
    gv: &mut GenVars,
    streams: &mut Streams,
    opts: &GenOptions,
    _noise: &Noise,
    _pass_config: &ConfigSection,
) {
    if !opts.flags.contains(crate::seeds::SeedFlags::SKYBLOCK) {
        return;
    }
    let mut rng = streams.pass_rng("Skyblock");
    super::skyblock::generate_skyblock_world(world, &mut rng, opts.flags, opts.micro_flags, opts.crimson, gv);
}

fn step_jungle(
    world: &mut World,
    gv: &mut GenVars,
    streams: &mut Streams,
    _opts: &GenOptions,
    _noise: &Noise,
    _pass_config: &ConfigSection,
) {
    // The faithful `JunglePass` draws from its own fresh per-pass stream
    // (the `WorldGenerator.cs:497` re-seed model — the Phase-1 contract).
    let jungle_origin_x = gv.jungle_origin_x;
    let (world_surface, rock_layer) = {
        let l = gv.layers();
        (l.world_surface, l.rock_layer)
    };
    let (water_line, lava_line) = (gv.water_line as f64, gv.lava_line as f64);
    let map = gv.map();
    biomes::pass_jungle(
        world,
        jungle_origin_x,
        world_surface,
        rock_layer,
        water_line,
        lava_line,
        map.left_beach_end,
        map.right_beach_start,
        &mut streams.pass_rng("Jungle"),
    );
}

