/// `Gem Caves` (`WorldGen.cs:17428`).
fn step_gem_caves(
    world: &mut World,
    _gv: &mut GenVars,
    streams: &mut Streams,
    _opts: &GenOptions,
    _noise: &Noise,
    _pass_config: &ConfigSection,
) {
    let mut rng = streams.pass_rng("Gem Caves");
    spider_gem_moss::pass_gem_caves(world, &mut rng, world.rock_layer, world.world_surface);
}

/// `Moss` (`WorldGen.cs:17472`) — the neon-moss biomes, the moss caves and
/// the scatters. The C#'s `GenVars.lavaLine`/`waterLine` (`GenVars.cs:62-64`)
/// are the port's `GenVars` fields (the terrain-fill step's product), the
/// depth anchors the arms key on.
fn step_moss(
    world: &mut World,
    gv: &mut GenVars,
    streams: &mut Streams,
    _opts: &GenOptions,
    _noise: &Noise,
    _pass_config: &ConfigSection,
) {
    let (rock_layer, water_line, lava_line) = (world.rock_layer, gv.water_line, gv.lava_line);
    let hell_top = gv.layers().hell_top;
    let mut rng = streams.pass_rng("Moss");
    spider_gem_moss::pass_moss(
        world,
        &mut rng,
        rock_layer,
        water_line as f64,
        lava_line as f64,
        hell_top,
    );
}

/// `Guide` (`WorldGen.cs:19685-19897`, `GenPassNameID.SpawnStarterNPCs`) —
/// the gen-time starter town NPCs. The pass reads `Main.spawnTileX/Y`, the
/// Spawn Point pass's product (`:19460-19588`); the port's Spawn Point is
/// the world tail's formula, so the adapter publishes it here at pass time
/// (the C# computes it BEFORE Guide too — more faithful than reading the
/// tail's late value). Classic worlds use the height-map anchor; remix
/// scans up from the bottom centre. The name rolls ride `pass_rng("Guide")`.
fn step_guide(
    world: &mut World,
    _gv: &mut GenVars,
    streams: &mut Streams,
    opts: &GenOptions,
    _noise: &Noise,
    _pass_config: &ConfigSection,
) {
    // The vanilla pass reads `Main.spawnTileX/Y`; the `spawn point` step
    // (`:19460-19588`) runs just before this one and its result rides
    // `world.spawn_x/spawn_y`. Reading the compact map formula here instead
    // would desync the Guide's home from the actual spawn.
    let (spawn_x, spawn_y) = (world.spawn_x, world.spawn_y);
    starter_npcs::pass_starter_npcs(
        world,
        opts,
        spawn_x,
        spawn_y,
        &mut streams.pass_rng("Guide"),
    );
}

